<script setup lang="ts">
import {readDraft,writeDraft,clearDraft,protectUnload} from '../lib/edit-protection';
import {confirmAction} from '../lib/dialog';import {onBeforeRouteLeave} from 'vue-router';
import DateTimePicker from '../components/DateTimePicker.vue';
import { ref,onMounted,watch,computed } from 'vue';import { api,catalog,loadCatalog } from '../lib/api';import type { Event,Category,RoleOption } from '../../shared/models';
const data=ref<{events:Event[];categories:Category[];roles:RoleOption[];mail_provider:string}|null>(null),error=ref(''),notice=ref(''),selected=ref(''),busy=ref(false);
const event=ref({name:'',year:new Date().getFullYear(),timezone:'Asia/Shanghai',opens_at:'',closes_at:'',submissions_open:false,wishes_open:true,active:true});const dictionary=ref({category_id:null as string|null,name:'',platform_id:'',staff_limit:null as number|null,verified:false,evidence_url:'',labels:''});
async function load(){data.value=await api('/api/admin/settings');await loadCatalog();}
function selectEvent(id:string){selected.value=id;const e=data.value?.events.find(x=>x.id===id);event.value=e?{name:e.name,year:e.year,timezone:e.timezone,opens_at:e.opens_at??'',closes_at:e.closes_at??'',submissions_open:!!e.submissions_open,wishes_open:!!e.wishes_open,active:!!e.active}:{name:'',year:new Date().getFullYear(),timezone:'Asia/Shanghai',opens_at:'',closes_at:'',submissions_open:false,wishes_open:true,active:true};}
async function saveEvent(){if(busy.value)return;busy.value=true;error.value='';try{const value={...event.value,opens_at:event.value.opens_at?new Date(event.value.opens_at).toISOString():null,closes_at:event.value.closes_at?new Date(event.value.closes_at).toISOString():null};if(selected.value)await api('/api/admin/events/'+selected.value,{...value,expectedVersion:data.value!.events.find(e=>e.id===selected.value)!.version},'PUT');else{const r=await api<{id:string}>('/api/admin/events',value);selected.value=r.id;}await load();selectEvent(selected.value);eventBase.value=JSON.stringify(event.value);persist();notice.value='活动已保存';}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
function selectCategory(id:string){const c=data.value?.categories.find(c=>c.id===id);if(!c){dictionary.value={category_id:null,name:'',platform_id:'',staff_limit:null,verified:false,evidence_url:'',labels:''};return;}dictionary.value={category_id:c.id,name:c.name,platform_id:c.platform_id??'',staff_limit:c.staff_limit,verified:false,evidence_url:data.value?.roles.filter(r=>r.category_id===c.id).at(-1)?.evidence_url??'',labels:data.value?.roles.filter(r=>r.category_id===c.id&&r.enabled).map(r=>r.label).join('\n')??''};}
async function saveDictionary(){if(busy.value)return;busy.value=true;error.value='';try{await api('/api/admin/bili-role-config',{...dictionary.value,staff_limit:dictionary.value.staff_limit?Number(dictionary.value.staff_limit):null,platform_id:dictionary.value.platform_id||null,labels:dictionary.value.labels.split('\n').map(x=>x.trim()).filter(Boolean)},'PUT');await load();dictionaryBase.value=JSON.stringify(dictionary.value);persist();notice.value='已建立新的职务字典版本，历史投稿保留原职务。';}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}

const eventBase=ref(''),dictionaryBase=ref('');let ready=false;
const eventDirty=computed(()=>!!eventBase.value&&JSON.stringify(event.value)!==eventBase.value),dictionaryDirty=computed(()=>!!dictionaryBase.value&&JSON.stringify(dictionary.value)!==dictionaryBase.value);
const dirty=computed(()=>eventDirty.value||dictionaryDirty.value);
function persist(){if(!ready)return;if(dirty.value){if(!writeDraft('settings',{selected:selected.value,event:event.value,dictionary:dictionary.value,eventVersion:data.value?.events.find(e=>e.id===selected.value)?.version}))notice.value='本机备份不可用，请保存后再离开。';}else clearDraft('settings');}
watch([event,dictionary],persist,{deep:true,flush:'sync'});
async function pick(id:string){if(busy.value)return;if(eventDirty.value&&!await confirmAction('切换活动将放弃尚未保存的活动资料，确定切换？'))return;ready=false;selectEvent(id);eventBase.value=JSON.stringify(event.value);ready=true;persist();}
async function pickCategory(id:string){if(busy.value)return;if(dictionaryDirty.value&&!await confirmAction('切换分区将放弃尚未保存的职务设置，确定切换？'))return;ready=false;selectCategory(id);dictionaryBase.value=JSON.stringify(dictionary.value);ready=true;persist();}
async function choose(e:globalThis.Event,category=false){const el=e.target as HTMLSelectElement;try{if(category)await pickCategory(el.value);else await pick(el.value);}finally{el.value=category?dictionary.value.category_id??'':selected.value;}}
async function discard(){if(!await confirmAction('放弃本机尚未保存的设置，重新读取服务器资料？'))return;ready=false;clearDraft('settings');await load();selectEvent(selected.value);selectCategory(dictionary.value.category_id??'');eventBase.value=JSON.stringify(event.value);dictionaryBase.value=JSON.stringify(dictionary.value);ready=true;notice.value='已重新读取服务器资料。';}
onMounted(async()=>{try{await load();selectEvent(catalog.eventId);eventBase.value=JSON.stringify(event.value);dictionaryBase.value=JSON.stringify(dictionary.value);const old=readDraft<{selected:string;event:typeof event.value;dictionary:typeof dictionary.value;eventVersion?:number}>('settings');if(old&&await confirmAction('发现本机未保存的活动或职务设置，是否恢复？')){selectEvent(old.selected);eventBase.value=JSON.stringify(event.value);selectCategory(old.dictionary.category_id??'');dictionaryBase.value=JSON.stringify(dictionary.value);if(old.eventVersion&&data.value?.events.find(e=>e.id===old.selected)?.version!==old.eventVersion)notice.value='服务器活动资料已经更新，恢复的本机内容请与当前设置核对后再保存。';else notice.value='已恢复本机未保存设置。';event.value=old.event;dictionary.value=old.dictionary;}else clearDraft('settings');ready=true;persist();}catch(e){error.value=(e as Error).message;}});
protectUnload(()=>dirty.value||busy.value);onBeforeRouteLeave(async()=>!busy.value&&(!dirty.value||await confirmAction('设置尚未保存，本机草稿会保留。确定离开？')));
</script>
<template><div class="page"><header class="page-head"><div><h1>活动设置</h1></div></header><p v-if="error" class="alert error" role="alert">{{ error }}</p><p v-if="notice" class="alert success" role="status">{{ notice }}</p><p v-if="dirty" class="hint" role="status">有未保存的设置 · 本机保留草稿 <button type="button" @click="discard">放弃修改</button></p><fieldset :disabled="busy||!data"><div class="grid two"><section class="paper"><h2>活动资料</h2><label>选择活动<select :value="selected" @change="choose($event)"><option value="">＋ 新建活动</option><option v-for="e in data?.events" :value="e.id">{{ e.name }}</option></select></label><form @submit.prevent="saveEvent"><label>活动名称<input v-model="event.name" required maxlength="100"></label><div class="grid two"><label>年份<input v-model.number="event.year" type="number" min="2000" max="2200" required></label><label>时区<input v-model="event.timezone" required placeholder="Asia/Shanghai"></label></div><DateTimePicker v-model="event.opens_at" label="征稿开始时间" :timezone="event.timezone"/><DateTimePicker v-model="event.closes_at" label="征稿结束时间" :timezone="event.timezone"/><label class="check"><input type="checkbox" v-model="event.submissions_open">开放征稿</label><label class="check"><input type="checkbox" v-model="event.wishes_open">开放祝福语投稿（独立于作品征稿）</label><label class="check"><input type="checkbox" v-model="event.active">活动可见</label><button class="primary" :disabled="busy">保存活动</button></form></section><section class="paper"><h2>B 站制作人员职务</h2><p class="hint">已内建活动分区与制作职务。若用于 B站联合投稿，请按实际投稿页核对平台标签及人数上限。</p><label>已有分区<select :value="dictionary.category_id??''" @change="choose($event,true)"><option value="">选择或新建</option><option v-for="c in data?.categories" :value="c.id">{{ c.name }}{{ c.verified_at?' · 已核实':c.origin==='festival-default'?' · 活动预设':' · 待核实' }}</option></select></label><form @submit.prevent="saveDictionary"><label>分区名称<input v-model="dictionary.name" required></label><div class="grid two"><label>平台分区 ID<input v-model="dictionary.platform_id"></label><label>人员上限（留空表示未确认）<input v-model.number="dictionary.staff_limit" type="number" min="1"></label></div><label>核实证据链接<input v-model="dictionary.evidence_url" type="url" required placeholder="https://…"></label><label>职务标签（每行一个）<textarea v-model="dictionary.labels" required rows="6" placeholder="严格复制该分区的可选职务"></textarea></label><label class="check"><input v-model="dictionary.verified" type="checkbox">我已核实这些标签与当前投稿页一致</label><button class="primary" :disabled="busy">保存字典新版本</button></form></section></div><section class="paper"><h2>邮件与访问</h2><p>当前邮件适配器：<code>{{ data?.mail_provider }}</code>。正式域名：<a href="https://usagi.mikanyan.com">usagi.mikanyan.com</a></p><p class="hint">超级管理员通过“管理员任免”管理普通管理员，不提供自助提权。邮件凭据通过 Cloudflare Secrets 设置，不在网页保存。</p></section></fieldset></div></template>
